        private static void OpenProjection(Window owner, DeepSystemsContext ctx, WorldIndex index, string sourceKind, string sourceId, string fingerprint, Func<ComplexSystemModel> factory)
        {
            Load(ctx); List<ComplexSystemModel> existing = Store.Models.Where(x => Eq(x.SourceKind, sourceKind) && Eq(x.SourceId, sourceId)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); ComplexSystemModel exact = existing.FirstOrDefault(x => Eq(x.SourceFingerprint, fingerprint)); if (exact != null) { OpenModel(owner, ctx, index, exact); return; }
            if (existing.Count > 0) { MessageBoxResult drift = MessageBox.Show(owner, "The source fingerprint has changed since the latest complexity projection.\n\nYES · create a traceable child revision\nNO · open the historical projection\nCANCEL · leave unchanged", "YOMI · SOURCE DRIFT BOUNDARY", MessageBoxButton.YesNoCancel, MessageBoxImage.Warning); if (drift == MessageBoxResult.No) { OpenModel(owner, ctx, index, existing[0]); return; } if (drift != MessageBoxResult.Yes) return; }
            ComplexSystemModel model = factory == null ? StarterModel("Untitled complex system", "Declared complex-system abstraction.") : factory(); if (model == null) return; model.Id = Id("complex-model"); model.ParentModelId = existing.Count == 0 ? null : existing[0].Id; model.SourceKind = sourceKind; model.SourceId = sourceId; model.SourceFingerprint = fingerprint; model.CreatedUtc = Now(); model.UpdatedUtc = model.CreatedUtc; model.Revision = existing.Count == 0 ? 1 : Math.Max(1, existing[0].Revision) + 1; Store.Models.Insert(0, model); Save(ctx); AppendLedger(ctx, "MODEL_PROJECTED", model.Id, sourceKind + ":" + sourceId + (existing.Count == 0 ? "" : " · source drift child of " + existing[0].Id), ComplexSystemsKernel.Fingerprint(model), ""); OpenModel(owner, ctx, index, model);
        }

