        private static void OpenRegistry(Window owner, DeepSystemsContext ctx, WorldIndex index) { Load(ctx); Window w = W(owner, "YOMI · COMPLEX SYSTEM MODEL REGISTRY", 1240, 820); DockPanel root = Shell("COMPLEX SYSTEM MODEL REGISTRY", CensusLine()); WrapPanel tools = new WrapPanel(); tools.Children.Add(Btn("CREATE MODEL", delegate { CreateModel(w, ctx, index); })); tools.Children.Add(Btn("RUN VAULT", delegate { OpenRunVault(w, ctx, "SIMULATION VAULT", false); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools); ListBox list = List(); list.ItemsSource = Store.Models.OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).ToList(); list.MouseDoubleClick += delegate { ComplexSystemModel m = list.SelectedItem as ComplexSystemModel; if (m != null) OpenModel(w, ctx, index, m); }; root.Children.Add(list); w.Content = root; w.Show(); }

        private static void OpenModel(Window owner, DeepSystemsContext ctx, WorldIndex index, ComplexSystemModel model)
        {
            Load(ctx); ComplexNetworkMetrics network = ComplexSystemsKernel.AnalyzeNetwork(model); Window w = W(owner, "YOMI · COMPLEX SYSTEM · " + (model.Name ?? model.Id), 1320, 880); DockPanel root = Shell((model.Status ?? "ACTIVE") + " · " + (model.Name ?? "COMPLEX SYSTEM"), (model.Description ?? "") + "\r\nFingerprint " + Short(ComplexSystemsKernel.Fingerprint(model), 24) + " · source " + (model.SourceKind ?? "MANUAL") + ":" + (model.SourceId ?? "∅") + " · " + network.ToString());
            WrapPanel tools = new WrapPanel { Margin = new Thickness(0, 6, 0, 8) }; tools.Children.Add(Btn("RUN", delegate { RunSimulation(w, ctx, model); })); tools.Children.Add(Btn("ENSEMBLE", delegate { RunEnsemble(w, ctx, model); })); tools.Children.Add(Btn("PHASE SWEEP", delegate { RunPhaseSweep(w, ctx, model); })); tools.Children.Add(Btn("RESILIENCE", delegate { RunResilience(w, model); })); tools.Children.Add(Btn("PERCOLATION", delegate { OpenPercolation(w, model); })); tools.Children.Add(Btn("INFORMATION", delegate { OpenInformationDynamics(w, model); })); tools.Children.Add(Btn("UPDATE MODES", delegate { OpenUpdateSemantics(w, model); })); tools.Children.Add(Btn("CONFIGURE", delegate { ConfigureModel(w, ctx, model); })); tools.Children.Add(Btn("ADD AGENT", delegate { AddAgent(w, ctx, model); })); tools.Children.Add(Btn("ADD EDGE", delegate { AddEdge(w, ctx, model); })); tools.Children.Add(Btn("RULES", delegate { OpenRules(w, ctx, index, model); })); tools.Children.Add(Btn("INTERVENTIONS", delegate { OpenInterventions(w, ctx, model); })); tools.Children.Add(Btn("PARAMETERS", delegate { EditParameters(w, ctx, model); })); tools.Children.Add(Btn("PREREGISTER", delegate { CreateCapsule(w, ctx, model); })); tools.Children.Add(Btn("FREEZE BASELINE", delegate { FreezeBaseline(w, ctx, model); })); tools.Children.Add(Btn("CREATE DOSSIER", delegate { CreateDossier(w, ctx, model); })); tools.Children.Add(Btn("OPTIMIZE ECOLOGY", delegate { OperationsResearchEmpire.OpenFromComplexSystem(w, ctx, index, model); })); tools.Children.Add(Btn("FORK", delegate { ForkModel(w, ctx, index, model); })); tools.Children.Add(Btn(Active(model.Status) ? "ARCHIVE" : "RESTORE", delegate { model.Status = Active(model.Status) ? "ARCHIVED" : "ACTIVE"; Touch(model); Save(ctx); AppendLedger(ctx, "MODEL_" + model.Status, model.Id, model.Name, ComplexSystemsKernel.Fingerprint(model), ""); w.Close(); })); tools.Children.Add(Btn("HADAL DESCENT", delegate { AbyssalKnowledgeEngine.DescendFromExternal(w, ctx, model.Name, model, StorePath(ctx), "$models:" + model.Id, "COMPLEX SYSTEMS › MODEL"); })); DockPanel.SetDock(tools, Dock.Top); root.Children.Add(tools);
            Grid body = new Grid(); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); body.ColumnDefinitions.Add(new ColumnDefinition()); ListBox agents = List(), edges = List(), artifacts = List(); agents.ItemsSource = (model.Agents ?? new List<ComplexAgentSpec>()).Cast<object>().Concat(new object[] { "Generated population remainder: " + Math.Max(0, model.PopulationSize - (model.Agents ?? new List<ComplexAgentSpec>()).Count).ToString(CultureInfo.InvariantCulture) }).ToList(); edges.ItemsSource = (model.Edges ?? new List<ComplexInteractionEdge>()).Count == 0 ? new List<object> { "Procedural topology · " + model.TopologyKind + " · mean degree " + model.MeanDegree } : model.Edges.Cast<object>().ToList(); artifacts.ItemsSource = Store.Runs.Where(x => Eq(x.ModelId, model.Id)).Cast<object>().Concat(Store.Ensembles.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.Sweeps.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.Baselines.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).Concat(Store.Capsules.Where(x => Eq(x.ModelId, model.Id)).Cast<object>()).ToList(); Grid.SetColumn(agents, 0); Grid.SetColumn(edges, 1); Grid.SetColumn(artifacts, 2); body.Children.Add(agents); body.Children.Add(edges); body.Children.Add(artifacts); root.Children.Add(body); w.Content = root; w.Show();
        }

        private static void CreateModel(Window owner, DeepSystemsContext ctx, WorldIndex index)
        {
            string name = Prompt(owner, "POPULATION FORGE", "Model name", "Emergent interaction world"); if (String.IsNullOrWhiteSpace(name)) return; string kind = Prompt(owner, "POPULATION KIND", "PEOPLE, MACHINES, COMPANIES, ANIMALS, PROTOCOLS, ACTORS…", "ACTORS"); if (kind == null) return; int population = Integer(Prompt(owner, "POPULATION SIZE", "2..4096", "256"), 256, 2, 4096); string topology = Prompt(owner, "TOPOLOGY", "RING, SMALL_WORLD, ERDOS_RENYI, SCALE_FREE, COMMUNITY, COMPLETE or EXPLICIT", "SMALL_WORLD"); if (topology == null) return; string dynamics = Prompt(owner, "DYNAMICS", "THRESHOLD_CONTAGION, SIR, BOUNDED_CONFIDENCE, VOTER, ISING, EVOLUTIONARY_GAME, CASCADE_FAILURE, COUPLED_MAP, CELLULAR_AUTOMATON or GENERIC_RULES", "THRESHOLD_CONTAGION"); if (dynamics == null) return; ComplexSystemModel m = StarterModel(name.Trim(), "Operator-authored heterogeneous population and interaction world."); m.Id = Id("complex-model"); m.PopulationKind = Short(kind.Trim().ToUpperInvariant(), 80); m.PopulationSize = population; m.TopologyKind = Short(topology.Trim().ToUpperInvariant(), 80); m.DynamicsKind = Short(dynamics.Trim().ToUpperInvariant(), 80); m.Seed = Integer(Prompt(owner, "DETERMINISTIC SEED", "Signed integer seed", "1337"), 1337, Int32.MinValue, Int32.MaxValue); m.Steps = Integer(Prompt(owner, "HORIZON", "1..8192 update steps", "256"), 256, 1, 8192); m.CreatedUtc = Now(); m.UpdatedUtc = m.CreatedUtc; Store.Models.Insert(0, m); Save(ctx); AppendLedger(ctx, "MODEL_CREATED", m.Id, m.Name, ComplexSystemsKernel.Fingerprint(m), ""); OpenModel(owner, ctx, index, m);
        }

        private static ComplexSystemModel StarterModel(string name, string description)
        {
            ComplexSystemModel m = new ComplexSystemModel { Name = name, Description = description, Status = "ACTIVE", PopulationSize = 256, TopologyKind = "SMALL_WORLD", DynamicsKind = "THRESHOLD_CONTAGION", UpdateMode = "SYNCHRONOUS", Seed = 1337, Steps = 256, MeanDegree = 8, LinkProbability = 0.04, RewireProbability = 0.08, CommunityCount = 4 }; m.Parameters["initial_active_fraction"] = 0.03; m.Parameters["threshold"] = 0.35; m.Parameters["susceptibility"] = 1; m.Parameters["transmission"] = 0.18; m.Parameters["recovery"] = 0.02; m.Parameters["noise"] = 0.001; m.Parameters["coupling"] = 0.1; m.Parameters["temperature"] = 1; m.Parameters["map_rate"] = 3.7; m.Parameters["capacity"] = 1; m.Parameters["initial_load"] = 0.4; m.Parameters["redistribution"] = 1; m.Parameters["performance_target_activity"] = 0; m.Parameters["payoff_reward"] = 1; m.Parameters["payoff_sucker"] = 0; m.Parameters["payoff_temptation"] = 1.5; m.Parameters["payoff_punishment"] = 0.1; m.Assumptions.Add("Agents, topology, parameters and update rules are declarations for synthetic reasoning, not measurements of a real population."); m.Assumptions.Add("Deterministic seed families support reproducibility but do not become probability distributions without calibration."); return m;
        }

        private static void RunSimulation(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { ComplexSimulationResult result = ComplexSystemsKernel.Simulate(model, model.Seed); string created = Now(), certificate = HashText(ComplexSystemsKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); ComplexRunRecord record = new ComplexRunRecord { Id = Id("complex-run"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = ComplexSystemsKernel.Fingerprint(model), CertificateHash = certificate, Label = "SEEDED EVOLUTION", Result = result }; Store.Runs.Insert(0, record); Save(ctx); AppendLedger(ctx, "SIMULATION_CERTIFIED", record.Id, model.Name, record.ModelFingerprint, certificate); OpenRows(owner, "SEEDED EVOLUTION", new object[] { record, result.Network }.Concat(result.Trace.Cast<object>()).Concat(result.TerminalSample.Cast<object>()).Concat(result.Audit.Cast<object>()).ToArray(), "Certificate " + certificate + " · conditional simulation, not observation or forecast"); }
        private static void RunEnsemble(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { int n = Integer(Prompt(owner, "ENSEMBLE SIZE", "1..512 deterministic seed worlds", "64"), 64, 1, 512); int offset = Integer(Prompt(owner, "SEED OFFSET", "Offset added to the model seed family", "0"), 0, Int32.MinValue, Int32.MaxValue); ComplexEnsembleResult result = ComplexSystemsKernel.RunEnsemble(model, n, offset); string created = Now(), certificate = HashText(ComplexSystemsKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); ComplexEnsembleRecord record = new ComplexEnsembleRecord { Id = Id("complex-ensemble"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = ComplexSystemsKernel.Fingerprint(model), CertificateHash = certificate, Result = result }; Store.Ensembles.Insert(0, record); Save(ctx); AppendLedger(ctx, "ENSEMBLE_CERTIFIED", record.Id, model.Name + " · n=" + n, record.ModelFingerprint, certificate); OpenRows(owner, "ENSEMBLE OBSERVATORY", new object[] { record, result }.Concat(result.TerminalBasins.OrderByDescending(x => x.Value).Select(x => (object)(x.Key + "   ·   " + x.Value + " worlds"))).Concat(result.Audit.Cast<object>()).ToArray(), "Certificate " + certificate + " · declared seed family only"); }
        private static void RunPhaseSweep(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { string key = Prompt(owner, "PHASE PARAMETER", "Parameter key to sweep", model.Parameters.Keys.FirstOrDefault() ?? "coupling"); if (String.IsNullOrWhiteSpace(key)) return; double current = Number(model.Parameters.ContainsKey(key) ? model.Parameters[key].ToString("R", CultureInfo.InvariantCulture) : "0.5", 0.5); double minimum = Number(Prompt(owner, "SWEEP MINIMUM", "Inclusive parameter minimum", (current * 0.25).ToString("R", CultureInfo.InvariantCulture)), current * 0.25), maximum = Number(Prompt(owner, "SWEEP MAXIMUM", "Inclusive parameter maximum", (Math.Abs(current) < 1e-12 ? 1 : current * 2).ToString("R", CultureInfo.InvariantCulture)), Math.Abs(current) < 1e-12 ? 1 : current * 2); int points = Integer(Prompt(owner, "SWEEP RESOLUTION", "3..129 parameter points", "17"), 17, 3, 129), replicates = Integer(Prompt(owner, "REPLICATES PER POINT", "2..128 seed worlds", "16"), 16, 2, 128); ComplexPhaseSweepResult result = ComplexSystemsKernel.SweepParameter(model, key.Trim(), minimum, maximum, points, replicates); string created = Now(), certificate = HashText(ComplexSystemsKernel.Fingerprint(model) + "|" + created + "|" + Json.Serialize(result)); ComplexSweepRecord record = new ComplexSweepRecord { Id = Id("complex-sweep"), ModelId = model.Id, CreatedUtc = created, ModelFingerprint = ComplexSystemsKernel.Fingerprint(model), CertificateHash = certificate, Result = result }; Store.Sweeps.Insert(0, record); Save(ctx); AppendLedger(ctx, "PHASE_SWEEP_CERTIFIED", record.Id, key + " · " + points + "x" + replicates, record.ModelFingerprint, certificate); OpenRows(owner, "PHASE TRANSITION ATLAS", new object[] { record, result }.Concat(result.Points.Cast<object>()).Concat(result.Audit.Cast<object>()).ToArray(), "Finite-size critical candidate · certificate " + certificate); }
        private static void RunResilience(Window owner, ComplexSystemModel model) { int step = Integer(Prompt(owner, "SHOCK STEP", "Update step for the synthetic perturbation", Math.Max(1, model.Steps / 3).ToString(CultureInfo.InvariantCulture)), Math.Max(1, model.Steps / 3), 1, model.Steps); double fraction = Number(Prompt(owner, "SHOCK FRACTION", "Fraction of eligible agents, 0..1", "0.10"), 0.1), magnitude = Number(Prompt(owner, "SHOCK MAGNITUDE", "Signed value shock", "-0.75"), -0.75); ComplexResilienceResult result = ComplexSystemsKernel.AnalyzeResilience(model, step, fraction, magnitude); OpenRows(owner, "RESILIENCE TRIBUNAL", new object[] { result }.Concat(result.Divergence.Select((x, i) => (object)("t=" + i.ToString(CultureInfo.InvariantCulture).PadLeft(6) + "   ·   divergence " + x.ToString("0.000000", CultureInfo.InvariantCulture)))).Concat(result.Audit.Cast<object>()).ToArray(), "Same-seed counterfactual baseline versus one explicit synthetic shock"); }
        private static void OpenPercolation(Window owner, ComplexSystemModel model) { ComplexPercolationResult result = ComplexSystemsKernel.AnalyzePercolation(model, 21, 16); OpenRows(owner, "PERCOLATION CRUCIBLE", new object[] { result }.Concat(result.Points.Cast<object>()).Concat(result.Audit.Cast<object>()).ToArray(), "Random removal ensemble versus static initial-degree attack · synthetic topology only"); }
        private static void OpenInformationDynamics(Window owner, ComplexSystemModel model) { ComplexInformationDynamicsResult result = ComplexSystemsKernel.AnalyzeInformationDynamics(model, model.Seed); OpenRows(owner, "INFORMATION DYNAMICS", new object[] { result, "early/late variance   ·   " + result.EarlyVariance.ToString("0.######", CultureInfo.InvariantCulture) + " / " + result.LateVariance.ToString("0.######", CultureInfo.InvariantCulture), "early/late AC₁   ·   " + result.EarlyAutocorrelation.ToString("0.######", CultureInfo.InvariantCulture) + " / " + result.LateAutocorrelation.ToString("0.######", CultureInfo.InvariantCulture), "change strength   ·   " + result.ChangePointStrength.ToString("0.######", CultureInfo.InvariantCulture), "predictive efficiency   ·   " + result.PredictiveEfficiency.ToString("0.######", CultureInfo.InvariantCulture) }.Concat(result.Audit.Cast<object>()).ToArray(), "Information-theoretic observables over the declared aggregate activity trace"); }
        private static void OpenUpdateSemantics(Window owner, ComplexSystemModel model) { ComplexUpdateSemanticsResult result = ComplexSystemsKernel.CompareUpdateSemantics(model, model.Seed); List<object> rows = new List<object> { result, result.Synchronous, result.Asynchronous, "certificate   ·   " + (result.CertificateHash ?? "∅") }; rows.AddRange(result.Audit.Cast<object>()); OpenRows(owner, "UPDATE-SEMANTICS BIFURCATION", rows, "Same model and seed; only event ordering changes"); }

        private static void ConfigureModel(Window owner, DeepSystemsContext ctx, ComplexSystemModel model)
        {
            string name = Prompt(owner, "MODEL CONFIGURATION", "Model name", model.Name); if (String.IsNullOrWhiteSpace(name)) return;
            string description = PromptLarge(owner, "MODEL DESCRIPTION", "Declared scope, mechanism and intended use", model.Description); if (description == null) return;
            string populationKind = Prompt(owner, "POPULATION KIND", "PEOPLE, MACHINES, COMPANIES, ANIMALS, PROTOCOLS, ACTORS…", model.PopulationKind ?? "ACTORS"); if (populationKind == null) return;
            object topologyChoice = ChooseObject(owner, "TOPOLOGY", "Select the procedural or explicit interaction topology", CurrentFirst(model.TopologyKind, new[] { "RING", "LATTICE", "SMALL_WORLD", "ERDOS_RENYI", "SCALE_FREE", "COMMUNITY", "COMPLETE", "EXPLICIT" })); if (topologyChoice == null) return;
            object dynamicsChoice = ChooseObject(owner, "DYNAMICS", "Select the native evolution law", CurrentFirst(model.DynamicsKind, new[] { "THRESHOLD_CONTAGION", "SIR", "BOUNDED_CONFIDENCE", "VOTER", "ISING", "EVOLUTIONARY_GAME", "CASCADE_FAILURE", "COUPLED_MAP", "CELLULAR_AUTOMATON", "GENERIC_RULES" })); if (dynamicsChoice == null) return;
            object updateChoice = ChooseObject(owner, "UPDATE SEMANTICS", "Select how agent transitions are ordered", CurrentFirst(model.UpdateMode, new[] { "SYNCHRONOUS", "ASYNCHRONOUS" })); if (updateChoice == null) return;
            string populationRaw = Prompt(owner, "POPULATION SIZE", "2..4096 agents", model.PopulationSize.ToString(CultureInfo.InvariantCulture)); if (populationRaw == null) return; int population = Integer(populationRaw, model.PopulationSize, 2, 4096);
            string stepsRaw = Prompt(owner, "HORIZON", "1..8192 update steps", model.Steps.ToString(CultureInfo.InvariantCulture)); if (stepsRaw == null) return; int steps = Integer(stepsRaw, model.Steps, 1, 8192);
            string degreeRaw = Prompt(owner, "MEAN DEGREE", "0..population-1 procedural neighbor target", model.MeanDegree.ToString(CultureInfo.InvariantCulture)); if (degreeRaw == null) return; int degree = Integer(degreeRaw, model.MeanDegree, 0, population - 1);
            string linkRaw = Prompt(owner, "LINK PROBABILITY", "0..1 random-link probability", model.LinkProbability.ToString("R", CultureInfo.InvariantCulture)); if (linkRaw == null) return; double linkProbability = Math.Max(0, Math.Min(1, Number(linkRaw, model.LinkProbability)));
            string rewireRaw = Prompt(owner, "REWIRE PROBABILITY", "0..1 small-world rewiring probability", model.RewireProbability.ToString("R", CultureInfo.InvariantCulture)); if (rewireRaw == null) return; double rewireProbability = Math.Max(0, Math.Min(1, Number(rewireRaw, model.RewireProbability)));
            string communityRaw = Prompt(owner, "COMMUNITIES", "1..population community count", model.CommunityCount.ToString(CultureInfo.InvariantCulture)); if (communityRaw == null) return; int communities = Integer(communityRaw, model.CommunityCount, 1, population);
            string seedRaw = Prompt(owner, "DETERMINISTIC SEED", "Signed 32-bit integer seed", model.Seed.ToString(CultureInfo.InvariantCulture)); if (seedRaw == null) return; int seed = Integer(seedRaw, model.Seed, Int32.MinValue, Int32.MaxValue);
            model.Name = Short(name.Trim(), 512); model.Description = Short(description.Trim(), MaxLongText); model.PopulationKind = Short(populationKind.Trim().ToUpperInvariant(), 80); model.TopologyKind = topologyChoice.ToString(); model.DynamicsKind = dynamicsChoice.ToString(); model.UpdateMode = updateChoice.ToString(); model.PopulationSize = population; model.Steps = steps; model.MeanDegree = degree; model.LinkProbability = linkProbability; model.RewireProbability = rewireProbability; model.CommunityCount = communities; model.Seed = seed; Touch(model); Save(ctx); string fingerprint = ComplexSystemsKernel.Fingerprint(model); AppendLedger(ctx, "MODEL_RECONFIGURED", model.Id, model.TopologyKind + " · " + model.DynamicsKind + " · " + model.UpdateMode, fingerprint, ""); MessageBox.Show(owner, "Configuration committed.\n\nFingerprint " + fingerprint, "YOMI · MODEL CONFIGURATION", MessageBoxButton.OK, MessageBoxImage.Information);
        }

        private static void OpenDynamicsLens(Window owner, DeepSystemsContext ctx, WorldIndex index, ComplexSystemModel model) { Window w = W(owner, "YOMI · CASCADE & CONTAGION LAB", 1120, 760); DockPanel root = Shell("CASCADE & CONTAGION LAB", model.Name + " · current dynamics " + model.DynamicsKind); WrapPanel tools = new WrapPanel(); foreach (string dynamics in new[] { "THRESHOLD_CONTAGION", "SIR", "CASCADE_FAILURE", "VOTER", "ISING", "CELLULAR_AUTOMATON" }) { string chosen = dynamics; tools.Children.Add(Btn(chosen, delegate { model.DynamicsKind = chosen; Touch(model); Save(ctx); AppendLedger(ctx, "DYNAMICS_SELECTED", model.Id, chosen, ComplexSystemsKernel.Fingerprint(model), ""); RunSimulation(w, ctx, model); })); } root.Children.Add(tools); w.Content = root; w.Show(); }
        private static void OpenEvolutionaryLens(Window owner, ComplexSystemModel model) { string original = model.DynamicsKind; model.DynamicsKind = "EVOLUTIONARY_GAME"; try { ComplexEnsembleResult result = ComplexSystemsKernel.RunEnsemble(model, 64, 0); OpenRows(owner, "EVOLUTIONARY ECOLOGY", new object[] { result }.Concat(result.TerminalBasins.Select(x => (object)(x.Key + "   ·   " + x.Value + " seed worlds"))).Concat(result.Audit.Cast<object>()).ToArray(), "Temporary evolutionary-game lens; model dynamics remain " + original); } finally { model.DynamicsKind = original; } }
        private static void OpenRunVault(Window owner, DeepSystemsContext ctx, string title, bool attractorsOnly) { Load(ctx); IEnumerable<object> rows = Store.Runs.Cast<object>().Concat(Store.Ensembles.Cast<object>()).Concat(Store.Sweeps.Cast<object>()); if (attractorsOnly) rows = Store.Runs.Where(x => x.Result != null && x.Result.AttractorDetected).Cast<object>().Concat(Store.Ensembles.Where(x => x.Result != null && x.Result.TerminalBasins.Count > 0).Cast<object>()); OpenRows(owner, title, rows.ToArray(), attractorsOnly ? "Repeated aggregate microstate hashes and ensemble terminal-basin families" : "Fingerprint-bound certified laboratory artifacts"); }

