        private static void EditParameters(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { string initial = String.Join(Environment.NewLine, model.Parameters.OrderBy(x => x.Key).Select(x => x.Key + "=" + x.Value.ToString("R", CultureInfo.InvariantCulture)).ToArray()); string raw = PromptLarge(owner, "PARAMETER MANIFOLD", "One key=value declaration per line", initial); if (raw == null) return; Dictionary<string, double> parsed = Pairs(raw); if (parsed.Count == 0) return; model.Parameters = parsed; Touch(model); Save(ctx); AppendLedger(ctx, "PARAMETERS_REPLACED", model.Id, parsed.Count + " declared parameters", ComplexSystemsKernel.Fingerprint(model), ""); }

