        private static void FreezeBaseline(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { string name = Prompt(owner, "FREEZE COMPLEX-SYSTEM BASELINE", "Immutable baseline name", model.Name + " · baseline " + Now()); if (String.IsNullOrWhiteSpace(name)) return; string reason = PromptLarge(owner, "BASELINE RATIONALE", "Why this exact population model must remain recoverable", "Preserve a reproducible reference before further topology, rule or parameter evolution."); if (reason == null) return; string snapshot = Json.Serialize(model), modelFingerprint = ComplexSystemsKernel.Fingerprint(model); ComplexModelBaseline parent = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id)); ComplexModelBaseline b = new ComplexModelBaseline { Id = Id("complex-baseline"), ModelId = model.Id, ParentBaselineId = parent == null ? null : parent.Id, Name = name.Trim(), Status = "FROZEN", FrozenUtc = Now(), Reason = reason.Trim(), ModelFingerprint = modelFingerprint, SnapshotJson = snapshot }; b.BaselineFingerprint = BaselineFingerprint(b); Store.Baselines.Insert(0, b); Save(ctx); AppendLedger(ctx, "BASELINE_FROZEN", b.Id, b.Name, modelFingerprint, b.BaselineFingerprint); OpenRows(owner, "IMMUTABLE BASELINE", b, "Recomputed " + BaselineFingerprint(b)); }
        private static string BaselineFingerprint(ComplexModelBaseline b) { return HashText((b.Id ?? "") + "|" + (b.ModelId ?? "") + "|" + (b.ParentBaselineId ?? "") + "|" + (b.Name ?? "") + "|" + (b.FrozenUtc ?? "") + "|" + (b.Reason ?? "") + "|" + (b.ModelFingerprint ?? "") + "|" + (b.SnapshotJson ?? "")); }
