        private static void CreateDossier(Window owner, DeepSystemsContext ctx, ComplexSystemModel model) { string title = Prompt(owner, "CREATE EMERGENCE DOSSIER", "Dossier title", "Bounded emergence claim · " + model.Name); if (String.IsNullOrWhiteSpace(title)) return; string claim = PromptLarge(owner, "BOUNDED CLAIM", "State only what the current declared model artifacts support", "Under the declared topology, rules, parameters and seed family, the simulated population exhibits a reproducible macroscopic pattern."); if (claim == null) return; ComplexRunRecord run = Store.Runs.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, ComplexSystemsKernel.Fingerprint(model))); ComplexEnsembleRecord ensemble = Store.Ensembles.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, ComplexSystemsKernel.Fingerprint(model))); ComplexSweepRecord sweep = Store.Sweeps.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, ComplexSystemsKernel.Fingerprint(model))); ComplexModelBaseline baseline = Store.Baselines.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, ComplexSystemsKernel.Fingerprint(model))); ComplexExperimentCapsule capsule = Store.Capsules.FirstOrDefault(x => Eq(x.ModelId, model.Id) && Eq(x.ModelFingerprint, ComplexSystemsKernel.Fingerprint(model))); ComplexScenarioDossier d = new ComplexScenarioDossier { Id = Id("complex-dossier"), ModelId = model.Id, RunId = run == null ? null : run.Id, EnsembleId = ensemble == null ? null : ensemble.Id, SweepId = sweep == null ? null : sweep.Id, BaselineId = baseline == null ? null : baseline.Id, CapsuleId = capsule == null ? null : capsule.Id, Title = title.Trim(), CreatedUtc = Now(), UpdatedUtc = Now(), ModelFingerprint = ComplexSystemsKernel.Fingerprint(model), BoundedClaim = claim.Trim(), EvidenceNodeIds = new List<string>(model.EvidenceNodeIds ?? new List<string>()) }; d.Unknowns.Add("External validity and calibration remain unresolved unless independently evidenced."); if (ensemble == null) d.Unknowns.Add("No matching ensemble is attached."); if (sweep == null) d.Unknowns.Add("No matching phase sweep is attached."); if (baseline == null) d.Unknowns.Add("No immutable matching baseline is attached."); if (capsule == null) d.Unknowns.Add("No preregistered experiment capsule is attached."); d.Dissent.Add("Absence of recorded dissent is not consensus and must not strengthen the bounded claim."); Store.Dossiers.Insert(0, d); Save(ctx); AppendLedger(ctx, "DOSSIER_CREATED", d.Id, d.Title, d.ModelFingerprint, ""); OpenRows(owner, "EMERGENCE DOSSIER", d, d.AuthorityBoundary); }
        private static void OpenDossiers(Window owner, DeepSystemsContext ctx) { Load(ctx); OpenRows(owner, "EMERGENCE DOSSIER VAULT", Store.Dossiers.ToArray(), "Claims remain attached to exact model fingerprints, alternatives, unknowns and dissent"); }

        private static void ForkModel(Window owner, DeepSystemsContext ctx, WorldIndex index, ComplexSystemModel source) { string name = Prompt(owner, "FORK COMPLEX SYSTEM", "Child model name", source.Name + " · branch"); if (String.IsNullOrWhiteSpace(name)) return; ComplexSystemModel child = Json.Deserialize<ComplexSystemModel>(Json.Serialize(source)); child.Id = Id("complex-model"); child.ParentModelId = source.Id; child.Name = name.Trim(); child.SourceKind = "MODEL_FORK"; child.SourceId = source.Id; child.SourceFingerprint = ComplexSystemsKernel.Fingerprint(source); child.Status = "ACTIVE"; child.Revision = Math.Max(1, source.Revision) + 1; child.CreatedUtc = Now(); child.UpdatedUtc = child.CreatedUtc; Store.Models.Insert(0, child); Save(ctx); AppendLedger(ctx, "MODEL_FORKED", child.Id, "parent " + source.Id, ComplexSystemsKernel.Fingerprint(child), ""); OpenModel(owner, ctx, index, child); }
        private static void OpenAudit(Window owner, DeepSystemsContext ctx) { Load(ctx); List<object> rows = new List<object>(); foreach (ComplexSystemModel model in Store.Models) { string fp = ComplexSystemsKernel.Fingerprint(model); rows.Add((model.Name ?? model.Id) + "   ·   " + fp); rows.AddRange(ComplexSystemsKernel.Audit(model).Cast<object>()); foreach (ComplexRunRecord run in Store.Runs.Where(x => Eq(x.ModelId, model.Id))) if (!Eq(run.ModelFingerprint, fp)) rows.Add("HISTORY · run " + run.Id + " correctly remains bound to historical fingerprint " + Short(run.ModelFingerprint, 20)); } foreach (ComplexModelBaseline b in Store.Baselines) if (!Eq(b.BaselineFingerprint, BaselineFingerprint(b))) rows.Add("BLOCKER · BASELINE_FINGERPRINT_MISMATCH · " + b.Id); rows.Add("LEDGER · " + VerifyLedger(ReadLedger(ctx, 32768))); OpenRows(owner, "LABORATORY AUDITOR", rows, "Structural, provenance, history and epistemic-boundary audit"); }
        private static void OpenLedger(Window owner, DeepSystemsContext ctx) { List<ComplexLabLedgerRecord> rows = ReadLedger(ctx, 32768); OpenRows(owner, "COMPLEX SYSTEMS INTEGRITY LEDGER", new object[] { VerifyLedger(rows) }.Concat(rows.OrderByDescending(x => x.Sequence).Cast<object>()).ToArray(), "Append-only SHA-256 chain · " + LedgerPath(ctx)); }

        private static void WithModel(Window owner, DeepSystemsContext ctx, Action<ComplexSystemModel> action) { ComplexSystemModel model = ChooseObject(owner, "SELECT COMPLEX SYSTEM", "Choose an active population model", Store.Models.Where(x => Active(x.Status)).OrderByDescending(x => x.UpdatedUtc ?? x.CreatedUtc).Cast<object>().ToList()) as ComplexSystemModel; if (model != null && action != null) action(model); }
        private static string CensusLine() { return Store.Models.Count + " models   ·   " + Store.Runs.Count + " runs   ·   " + Store.Ensembles.Count + " ensembles   ·   " + Store.Sweeps.Count + " phase sweeps   ·   " + Store.Capsules.Count + " preregistrations   ·   " + Store.Baselines.Count + " baselines   ·   " + Store.Dossiers.Count + " dossiers"; }

        private static void Load(DeepSystemsContext ctx) { lock (Gate) { if (Store != null && Eq(LoadedRoot, ctx.StateRoot)) return; LoadedRoot = ctx.StateRoot; Store = null; string path = StorePath(ctx); if (File.Exists(path)) try { Store = Json.Deserialize<ComplexSystemsStore>(File.ReadAllText(path, Encoding.UTF8)); } catch { PreserveCorrupt(path); } if (Store == null && File.Exists(path + ".previous")) try { Store = Json.Deserialize<ComplexSystemsStore>(File.ReadAllText(path + ".previous", Encoding.UTF8)); } catch { } if (Store == null) Store = new ComplexSystemsStore(); NormalizeStore(); } }
        private static void NormalizeStore() { if (Store == null) Store = new ComplexSystemsStore(); Store.Schema = 1; Store.Models = Store.Models ?? new List<ComplexSystemModel>(); Store.Runs = Store.Runs ?? new List<ComplexRunRecord>(); Store.Ensembles = Store.Ensembles ?? new List<ComplexEnsembleRecord>(); Store.Sweeps = Store.Sweeps ?? new List<ComplexSweepRecord>(); Store.Capsules = Store.Capsules ?? new List<ComplexExperimentCapsule>(); Store.Baselines = Store.Baselines ?? new List<ComplexModelBaseline>(); Store.Dossiers = Store.Dossiers ?? new List<ComplexScenarioDossier>(); Store.RecentQuestions = Store.RecentQuestions ?? new List<string>(); foreach (ComplexSystemModel m in Store.Models) { m.Parameters = new Dictionary<string, double>(m.Parameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); m.Agents = (m.Agents ?? new List<ComplexAgentSpec>()).Take(MaxAgents).ToList(); m.Edges = (m.Edges ?? new List<ComplexInteractionEdge>()).Take(MaxEdges).ToList(); m.Rules = (m.Rules ?? new List<ComplexRuleSpec>()).Take(MaxRules).ToList(); m.Interventions = (m.Interventions ?? new List<ComplexInterventionSpec>()).Take(MaxInterventions).ToList(); m.Assumptions = m.Assumptions ?? new List<string>(); m.EvidenceNodeIds = (m.EvidenceNodeIds ?? new List<string>()).Take(MaxEvidence).ToList(); foreach (ComplexAgentSpec a in m.Agents) { a.Traits = new Dictionary<string, double>(a.Traits ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); a.EvidenceNodeIds = a.EvidenceNodeIds ?? new List<string>(); } foreach (ComplexInteractionEdge e in m.Edges) e.EvidenceNodeIds = e.EvidenceNodeIds ?? new List<string>(); foreach (ComplexRuleSpec r in m.Rules) r.EvidenceNodeIds = r.EvidenceNodeIds ?? new List<string>(); foreach (ComplexInterventionSpec x in m.Interventions) x.EvidenceNodeIds = x.EvidenceNodeIds ?? new List<string>(); } foreach (ComplexRunRecord r in Store.Runs) r.Notes = r.Notes ?? new List<string>(); foreach (ComplexExperimentCapsule c in Store.Capsules) { c.FrozenParameters = new Dictionary<string, double>(c.FrozenParameters ?? new Dictionary<string, double>(), StringComparer.OrdinalIgnoreCase); c.Assumptions = c.Assumptions ?? new List<string>(); c.Falsifiers = c.Falsifiers ?? new List<string>(); c.EvidenceNodeIds = c.EvidenceNodeIds ?? new List<string>(); } foreach (ComplexScenarioDossier d in Store.Dossiers) { d.Mechanisms = d.Mechanisms ?? new List<string>(); d.Alternatives = d.Alternatives ?? new List<string>(); d.Unknowns = d.Unknowns ?? new List<string>(); d.Dissent = d.Dissent ?? new List<string>(); d.EvidenceNodeIds = d.EvidenceNodeIds ?? new List<string>(); } }
        private static void TrimStore() { NormalizeStore(); Store.Models = Store.Models.Take(MaxModels).ToList(); Store.Runs = Store.Runs.Take(MaxRuns).ToList(); Store.Ensembles = Store.Ensembles.Take(MaxEnsembles).ToList(); Store.Sweeps = Store.Sweeps.Take(MaxSweeps).ToList(); Store.Capsules = Store.Capsules.Take(MaxCapsules).ToList(); Store.Baselines = Store.Baselines.Take(MaxBaselines).ToList(); Store.Dossiers = Store.Dossiers.Take(MaxDossiers).ToList(); Store.RecentQuestions = Store.RecentQuestions.Take(256).ToList(); }
        private static void Save(DeepSystemsContext ctx) { lock (Gate) { TrimStore(); Store.Revision = Math.Max(0, Store.Revision) + 1; Store.UpdatedUtc = Now(); Store.LastCommitId = Id("complex-commit"); string path = StorePath(ctx); Directory.CreateDirectory(Path.GetDirectoryName(path)); AtomicWrite(path, Json.Serialize(Store)); } }
        private static void AtomicWrite(string path, string text) { string temp = path + ".tmp." + Guid.NewGuid().ToString("N"); File.WriteAllText(temp, text ?? "", new UTF8Encoding(false)); if (File.Exists(path)) { string previous = path + ".previous"; try { File.Replace(temp, path, previous, true); return; } catch { try { File.Copy(path, previous, true); } catch { } } } if (File.Exists(path)) File.Delete(path); File.Move(temp, path); }
        private static void PreserveCorrupt(string path) { try { if (!File.Exists(path)) return; byte[] bytes = File.ReadAllBytes(path); string destination = path + ".corrupt." + HashBytes(bytes).Substring(0, 16) + ".json"; if (!File.Exists(destination)) File.Copy(path, destination); } catch { } }
        private static string StorePath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-complex-systems-laboratory.json"); }
        private static string LedgerPath(DeepSystemsContext ctx) { return Path.Combine(ctx.StateRoot, "controller-complex-systems-laboratory-ledger.jsonl"); }
        private static void AppendLedger(DeepSystemsContext ctx, string evt, string subject, string detail, string fingerprint, string certificate) { lock (Gate) try { Directory.CreateDirectory(ctx.StateRoot); List<ComplexLabLedgerRecord> prior = ReadLedger(ctx, 32768); ComplexLabLedgerRecord last = prior.OrderByDescending(x => x.Sequence).FirstOrDefault(); ComplexLabLedgerRecord r = new ComplexLabLedgerRecord { Schema = 1, Sequence = last == null ? 1 : last.Sequence + 1, Utc = Now(), Event = Short(evt, 120), Subject = Short(subject, 512), Detail = Short(detail, MaxLongText), CorrelationId = Store == null ? "" : Store.LastCommitId, ModelFingerprint = Short(fingerprint, 128), CertificateHash = Short(certificate, 128), PrevHash = last == null ? new string('0', 64) : last.EntryHash }; r.EntryHash = LedgerHash(r); byte[] bytes = Encoding.UTF8.GetBytes(Json.Serialize(r) + Environment.NewLine); using (FileStream stream = new FileStream(LedgerPath(ctx), FileMode.Append, FileAccess.Write, FileShare.Read, 4096, FileOptions.WriteThrough)) { stream.Write(bytes, 0, bytes.Length); stream.Flush(); } } catch { } }
        private static List<ComplexLabLedgerRecord> ReadLedger(DeepSystemsContext ctx, int cap) { List<ComplexLabLedgerRecord> rows = new List<ComplexLabLedgerRecord>(); if (!File.Exists(LedgerPath(ctx))) return rows; try { foreach (string line in TakeLast(File.ReadLines(LedgerPath(ctx)).Where(x => !String.IsNullOrWhiteSpace(x)), cap)) try { ComplexLabLedgerRecord row = Json.Deserialize<ComplexLabLedgerRecord>(line); if (row != null) rows.Add(row); } catch { } } catch { } return rows; }
        private static string VerifyLedger(List<ComplexLabLedgerRecord> rows) { if (rows == null || rows.Count == 0) return "EMPTY LEDGER"; rows = rows.OrderBy(x => x.Sequence).ToList(); long expected = rows[0].Sequence; string prior = expected == 1 ? new string('0', 64) : rows[0].PrevHash; foreach (ComplexLabLedgerRecord row in rows) { if (row.Sequence != expected) return "CHAIN GAP @ " + expected; if (!Eq(row.PrevHash, prior)) return "PREV HASH MISMATCH @ " + row.Sequence; if (!Eq(row.EntryHash, LedgerHash(row))) return "ENTRY HASH MISMATCH @ " + row.Sequence; expected++; prior = row.EntryHash; } return "CHAIN VERIFIED · " + rows.Count.ToString(CultureInfo.InvariantCulture) + " RECORDS"; }
        private static string LedgerHash(ComplexLabLedgerRecord r) { return HashText(r.Schema + "|" + r.Sequence + "|" + (r.Utc ?? "") + "|" + (r.Event ?? "") + "|" + (r.Subject ?? "") + "|" + (r.Detail ?? "") + "|" + (r.CorrelationId ?? "") + "|" + (r.ModelFingerprint ?? "") + "|" + (r.CertificateHash ?? "") + "|" + (r.PrevHash ?? "")); }

        private static void Touch(ComplexSystemModel m) { m.Revision = Math.Max(1, m.Revision) + 1; m.UpdatedUtc = Now(); }
        private static bool Active(string status) { return !Eq(status, "ARCHIVED") && !Eq(status, "DISABLED") && !Eq(status, "RETIRED") && !Eq(status, "REJECTED"); }
        private static bool Eq(string a, string b) { return String.Equals(a ?? "", b ?? "", StringComparison.OrdinalIgnoreCase); }
        private static IList<object> CurrentFirst(string current, IEnumerable<string> values) { return (values ?? Enumerable.Empty<string>()).OrderBy(x => Eq(x, current) ? 0 : 1).ThenBy(x => x).Cast<object>().ToList(); }
        private static double Normalize(double value, double minimum, double maximum) { if (Double.IsNaN(value) || Double.IsInfinity(value)) return 0; if (maximum <= minimum) return value >= 0 ? 1 : 0; return Math.Max(0, Math.Min(1, (value - minimum) / (maximum - minimum))); }
        private static double Number(string raw, double fallback) { double value; return Double.TryParse(raw, NumberStyles.Float, CultureInfo.InvariantCulture, out value) && !Double.IsNaN(value) && !Double.IsInfinity(value) ? value : fallback; }
        private static int Integer(string raw, int fallback, int minimum, int maximum) { int value; if (!Int32.TryParse(raw, NumberStyles.Integer, CultureInfo.InvariantCulture, out value)) value = fallback; return Math.Max(minimum, Math.Min(maximum, value)); }
        private static Dictionary<string, double> Pairs(string raw) { Dictionary<string, double> result = new Dictionary<string, double>(StringComparer.OrdinalIgnoreCase); foreach (string line in (raw ?? "").Split(new[] { '\r', '\n', ';' }, StringSplitOptions.RemoveEmptyEntries)) { int at = line.IndexOf('='); if (at > 0) { string key = SafeKey(line.Substring(0, at).Trim()); if (!String.IsNullOrWhiteSpace(key)) result[key] = Number(line.Substring(at + 1).Trim(), 0); } } return result; }
        private static string SafeKey(string value) { StringBuilder s = new StringBuilder(); foreach (char c in (value ?? "").ToLowerInvariant()) if (Char.IsLetterOrDigit(c) || c == '_') s.Append(c); else if (s.Length > 0 && s[s.Length - 1] != '_') s.Append('_'); return s.ToString().Trim('_'); }
        private static string Short(string value, int cap) { value = value ?? ""; cap = Math.Max(1, cap); return value.Length <= cap ? value : value.Substring(0, cap - 1) + "…"; }
        private static string HashText(string value) { return HashBytes(Encoding.UTF8.GetBytes(value ?? "")); }
        private static string HashBytes(byte[] value) { using (SHA256 hash = SHA256.Create()) return BitConverter.ToString(hash.ComputeHash(value ?? new byte[0])).Replace("-", "").ToLowerInvariant(); }
        private static string Id(string prefix) { return prefix + "-" + DateTime.UtcNow.ToString("yyyyMMddHHmmssfff", CultureInfo.InvariantCulture) + "-" + Guid.NewGuid().ToString("N").Substring(0, 8); }
        private static string Now() { return DateTime.UtcNow.ToString("o", CultureInfo.InvariantCulture); }
        private static IEnumerable<TValue> TakeLast<TValue>(IEnumerable<TValue> source, int count) { Queue<TValue> q = new Queue<TValue>(); foreach (TValue item in source ?? Enumerable.Empty<TValue>()) { q.Enqueue(item); if (q.Count > count) q.Dequeue(); } foreach (TValue item in q) yield return item; }

        private static Window W(Window owner, string title, double width, double height) { return new Window { Title = title, Width = width, Height = height, MinWidth = Math.Min(width, 820), MinHeight = Math.Min(height, 560), Background = Bg, Foreground = Text, WindowStartupLocation = WindowStartupLocation.CenterOwner, Owner = owner, FontFamily = new FontFamily("Segoe UI") }; }
        private static DockPanel Shell(string title, string subtitle) { DockPanel root = new DockPanel { Margin = new Thickness(16) }; StackPanel head = new StackPanel { Margin = new Thickness(0, 0, 0, 10) }; head.Children.Add(T(title, 24, Text, FontWeights.Bold)); head.Children.Add(T(subtitle, 12, Muted, FontWeights.Normal)); DockPanel.SetDock(head, Dock.Top); root.Children.Add(head); return root; }
        private static TextBlock T(string value, double size, Brush foreground, FontWeight weight) { return new TextBlock { Text = value ?? "", FontSize = size, Foreground = foreground, FontWeight = weight, TextWrapping = TextWrapping.Wrap, Margin = new Thickness(0, 2, 0, 2) }; }
        private static Button Btn(string label, RoutedEventHandler click) { Button button = new Button { Content = label, Margin = new Thickness(0, 0, 8, 8), Padding = new Thickness(12, 7, 12, 7), Background = Raised, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), MinWidth = 112 }; if (click != null) button.Click += click; return button; }
        private static ListBox List() { return new ListBox { Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), Margin = new Thickness(0, 6, 6, 0), Padding = new Thickness(5), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; }
        private static void Portal(Panel parent, string badge, string title, string description, Action open) { Button button = new Button { Width = 360, Height = 120, Margin = new Thickness(0, 0, 10, 10), Padding = new Thickness(12), Background = Surface, Foreground = Text, BorderBrush = Border, BorderThickness = new Thickness(1), HorizontalContentAlignment = HorizontalAlignment.Stretch }; StackPanel content = new StackPanel(); content.Children.Add(T(badge + "   " + title, 14, Accent, FontWeights.Bold)); content.Children.Add(T(description, 11.5, Muted, FontWeights.Normal)); button.Content = content; button.Click += delegate { if (open != null) open(); }; parent.Children.Add(button); }
        private static Brush B(string hex) { return new SolidColorBrush((Color)ColorConverter.ConvertFromString(hex)); }
        private static string Prompt(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 680, 290); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxShortText, Margin = new Thickness(0, 8, 0, 10), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(8) }; DockPanel.SetDock(editor, Dock.Top); root.Children.Add(editor); WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right }; string result = null; buttons.Children.Add(Btn("OK", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); root.Children.Add(buttons); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static string PromptLarge(Window owner, string title, string label, string initial) { Window w = W(owner, "YOMI · " + title, 800, 560); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); TextBox editor = new TextBox { Text = initial ?? "", MaxLength = MaxLongText, AcceptsReturn = true, AcceptsTab = true, TextWrapping = TextWrapping.Wrap, VerticalScrollBarVisibility = ScrollBarVisibility.Auto, Margin = new Thickness(0, 8, 0, 0), Background = Surface, Foreground = Text, BorderBrush = Border, Padding = new Thickness(10), FontFamily = new FontFamily("Cascadia Mono, Consolas") }; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; string result = null; buttons.Children.Add(Btn("SAVE", delegate { result = editor.Text; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(editor); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static object ChooseObject(Window owner, string title, string label, IList<object> choices) { Window w = W(owner, "YOMI · " + title, 720, 500); DockPanel root = new DockPanel { Margin = new Thickness(16) }; TextBlock caption = T(label, 12, Muted, FontWeights.Normal); DockPanel.SetDock(caption, Dock.Top); root.Children.Add(caption); ListBox list = List(); list.ItemsSource = choices ?? new List<object>(); if (list.Items.Count > 0) list.SelectedIndex = 0; WrapPanel buttons = new WrapPanel { HorizontalAlignment = HorizontalAlignment.Right, Margin = new Thickness(0, 10, 0, 0) }; object result = null; buttons.Children.Add(Btn("SELECT", delegate { result = list.SelectedItem; w.DialogResult = true; })); buttons.Children.Add(Btn("CANCEL", delegate { w.DialogResult = false; })); list.MouseDoubleClick += delegate { result = list.SelectedItem; if (result != null) w.DialogResult = true; }; DockPanel.SetDock(buttons, Dock.Bottom); root.Children.Add(buttons); root.Children.Add(list); w.Content = root; bool? accepted = w.ShowDialog(); return accepted == true ? result : null; }
        private static void OpenRows(Window owner, string title, object value, string subtitle) { IEnumerable<object> rows = value as IEnumerable<object>; OpenRows(owner, title, rows == null ? new object[] { value } : rows.ToArray(), subtitle); }
        private static void OpenRows(Window owner, string title, IList<object> rows, string subtitle) { Window w = W(owner, "YOMI · " + title, 1240, 830); DockPanel root = Shell(title, subtitle); ListBox list = List(); list.ItemsSource = rows ?? new List<object>(); root.Children.Add(list); w.Content = root; w.Show(); }
    }
}
